def check_pristine(name: str, root: Path) -> None:
    """A fetched corpus holds only the pinned commit's ``*.py`` files. OXIDE captures every
    file, so a stray one (``__pycache__``, ``.pytest_cache``: something ran code in the corpus)
    moves the snapshot and lexical statistics while ``identity`` still matches."""
    stray = sorted(p.relative_to(root).as_posix() for p in root.rglob("*") if p.is_file() and p.suffix != ".py")
